#include <vector>

using namespace std;

class Solution {
public:
    long long minOperations(vector<vector<int>>& queries) {
        long long ans = 0;
        for (const auto& q : queries) {
            long long l = q[0];
            long long r = q[1];
            long long op = 0;
            long long i = 0;
            long long mn = l;
            long long t = 1;

            while (t <= r) {
                if (t > mn) {
                    if (t <= r) {
                        op += (t - mn) * i;
                    } else {
                        op += (r - mn + 1) * i;
                    }
                    mn = t;
                }
                i++;
                t = 1LL << (i << 1);
            }

            if (mn <= r) {
                op += (r - mn + 1) * i;
            }

            ans += (op + 1) / 2;
        }

        return ans;
    }
};

class Solution {
    public long minOperations(int[][] queries) {
        long ans = 0;
        for (int[] q : queries) {
            long l = q[0];
            long r = q[1];
            long op = 0;
            long i = 0;
            long mn = l;
            long t = 1;

            while (t <= r) {
                if (t > mn) {
                    if (t <= r) {
