var minOperations = function(queries) {
    let ans = 0n;
    for (const [l, r] of queries) {
        let op = 0n;
        let i = 0n;
        let mn = BigInt(l);
        const rBig = BigInt(r);
        let t = 1n;

        while (t <= rBig) {
            if (t > mn) {
                if (t <= rBig) {
                    op += (t - mn) * i;
                } else {
                    op += (rBig - mn + 1n) * i;
                }
                mn = t;
            }
            i++;
            t = 1n << (i << 1n);
        }

        if (mn <= rBig) {
            op += (rBig - mn + 1n) * i;
        }

        ans += (op + 1n) / 2n;
    }

    return Number(ans);
};
